"""
Node 11b - IBKR Send Orders FX

Insert between:
  11 Validate Enforce Safety FX -> [11b] -> 12 Simulate Fills FX

Dry-run behavior:
  IBKR_DRY_RUN=true keeps the workflow sandbox-only and does not call the
  broker by default. Set IBKR_SEND_DRY_RUN_TO_BROKER=true to exercise the
  ibkr-broker dry-run endpoint while still sending no live IBKR order.

Live behavior:
  IBKR_DRY_RUN=false posts pending orders to ibkr-broker. Orders rejected by
  the broker are marked broker_error, so node 12 will not create simulated
  fills for failed live submissions.
"""

import json
import os
import time
import uuid
import urllib.request
from urllib.error import URLError

BROKER_URL = os.environ.get("IBKR_BROKER_URL", "http://ibkr-broker:8080")
DRY_RUN = os.environ.get("IBKR_DRY_RUN", "true").lower() != "false"
SEND_DRY_RUN_TO_BROKER = os.environ.get("IBKR_SEND_DRY_RUN_TO_BROKER", "false").lower() == "true"
REQUIRE_PAPER_ACCOUNT = os.environ.get("IBKR_REQUIRE_PAPER_ACCOUNT", "true").lower() != "false"
PAPER_ACCOUNT_PREFIXES = tuple(
    p.strip().upper()
    for p in os.environ.get("IBKR_PAPER_ACCOUNT_PREFIXES", "DU").split(",")
    if p.strip()
)
FILL_CONFIRM_SECONDS = max(0, int(float(os.environ.get("IBKR_FILL_CONFIRM_SECONDS", "25") or 25)))
FILL_POLL_INTERVAL_SECONDS = max(1, int(float(os.environ.get("IBKR_FILL_POLL_INTERVAL_SECONDS", "5") or 5)))


def deterministic_client_order_id(seed: str) -> str:
    return str(uuid.uuid5(uuid.NAMESPACE_URL, seed))


def broker_order_id(result):
    raw = result.get("ibkr_response") or result.get("details") or result
    if isinstance(raw, list) and raw:
        return raw[0].get("order_id") or raw[0].get("orderId") or raw[0].get("id")
    if isinstance(raw, dict):
        return raw.get("order_id") or raw.get("orderId") or raw.get("id")
    return None


def broker_result_error(result):
    raw = result.get("ibkr_response") or result.get("details") or result
    rows = raw if isinstance(raw, list) else [raw] if isinstance(raw, dict) else []
    messages = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        for field in ("error", "message", "warning", "text"):
            value = row.get(field)
            if isinstance(value, list):
                messages.extend(str(v) for v in value if str(v).strip())
            elif value:
                messages.append(str(value))
        action = str(row.get("action") or "").lower()
        status = str(row.get("status") or "").lower()
        if "reject" in action or "rejected" in status or row.get("error"):
            return " | ".join(messages) or action or status or "IBKR_ORDER_REJECTED"
    if result.get("error"):
        return str(result.get("error"))
    return ""


def normalize_order_type(value):
    text = str(value or "MKT").strip().upper()
    if text == "MARKET":
        return "MKT"
    if text == "LIMIT":
        return "LMT"
    return text or "MKT"


def get_json(path: str, timeout: int = 12):
    req = urllib.request.Request(f"{BROKER_URL}{path}", headers={"Accept": "application/json"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8"))


def paper_account_ids(positions_payload):
    ids = []
    for row in positions_payload or []:
        acct = str(row.get("acctId") or row.get("accountId") or "").strip().upper()
        if acct and acct not in ids:
            ids.append(acct)
    return ids


def possible_fill_keys(fill):
    keys = set()
    for field in (
        "order_ref",
        "orderRef",
        "cOID",
        "client_order_id",
        "clientOrderId",
        "order_id",
        "orderId",
    ):
        value = fill.get(field)
        if value is not None and str(value).strip():
            keys.add(str(value).strip())
    return keys


def build_fill_map(fills_payload):
    out = {}
    for fill in fills_payload or []:
        if not isinstance(fill, dict):
            continue
        for key in possible_fill_keys(fill):
            out.setdefault(key, fill)
    return out


def poll_recent_fills(order_keys):
    if not order_keys or FILL_CONFIRM_SECONDS <= 0:
        return {}, []
    deadline = time.time() + FILL_CONFIRM_SECONDS
    last_payload = []
    while True:
        try:
            last_payload = get_json("/fills", timeout=15)
            fill_map = build_fill_map(last_payload)
            matched = {key: fill_map[key] for key in order_keys if key in fill_map}
            if matched or time.time() >= deadline:
                return matched, last_payload
        except Exception:
            if time.time() >= deadline:
                return {}, last_payload
        time.sleep(min(FILL_POLL_INTERVAL_SECONDS, max(0.0, deadline - time.time())))


ctx = (_items or [{"json": {}}])[0].get("json", {})
executable_orders = ctx.get("executable_orders") or []
run_id = ctx.get("run_id") or ""

for idx, order in enumerate(executable_orders, start=1):
    if not order.get("order_id"):
        order["order_id"] = f"ORD_{run_id}_{idx:03d}"
    if not order.get("client_order_id"):
        seed = "|".join(
            [
                str(run_id),
                str(order.get("order_id") or ""),
                str(order.get("pair") or ""),
                str(order.get("side") or ""),
                str(order.get("size_lots") or ""),
            ]
        )
        order["client_order_id"] = deterministic_client_order_id(seed)

ibkr_results = []
ibkr_errors = []
broker_called = False
broker_health = {}
broker_positions = []
broker_fills = []
matched_fills = {}
broker_dry_run = None

pending_orders = [o for o in executable_orders if o.get("status") == "pending"]

if pending_orders and (not DRY_RUN or SEND_DRY_RUN_TO_BROKER):
    try:
        broker_health = get_json("/health")
        broker_dry_run = bool(broker_health.get("dry_run"))
        authenticated = bool(broker_health.get("authenticated"))
        if not authenticated and not DRY_RUN:
            ibkr_errors.extend(
                {
                    "order_id": o.get("order_id"),
                    "client_order_id": o.get("client_order_id"),
                    "error": "IBKR_BROKER_NOT_AUTHENTICATED",
                }
                for o in pending_orders
            )
        elif not DRY_RUN and broker_dry_run:
            ibkr_errors.extend(
                {
                    "order_id": o.get("order_id"),
                    "client_order_id": o.get("client_order_id"),
                    "error": "IBKR_BROKER_STILL_IN_DRY_RUN",
                }
                for o in pending_orders
            )
        else:
            if REQUIRE_PAPER_ACCOUNT and not DRY_RUN:
                broker_positions = get_json("/positions")
                account_ids = paper_account_ids(broker_positions)
                if not account_ids or not all(acct.startswith(PAPER_ACCOUNT_PREFIXES) for acct in account_ids):
                    ibkr_errors.extend(
                        {
                            "order_id": o.get("order_id"),
                            "client_order_id": o.get("client_order_id"),
                            "error": f"IBKR_PAPER_ACCOUNT_GUARD_FAILED: accounts={account_ids}",
                        }
                        for o in pending_orders
                    )

            if not ibkr_errors:
                payload = {
                    "orders": [
                        {
                            "pair": o["pair"],
                            "side": o["side"],
                            "size_lots": float(o.get("size_lots", 0)),
                            "order_id": o["order_id"],
                            "client_order_id": o["client_order_id"],
                            "order_type": normalize_order_type(o.get("order_type")),
                            "limit_price": o.get("limit_price"),
                        }
                        for o in pending_orders
                    ],
                    "run_id": run_id,
                }

                broker_called = True
                req = urllib.request.Request(
                    f"{BROKER_URL}/orders/fx",
                    data=json.dumps(payload).encode("utf-8"),
                    headers={"Content-Type": "application/json"},
                    method="POST",
                )
                with urllib.request.urlopen(req, timeout=15) as resp:
                    response_data = json.loads(resp.read().decode("utf-8"))
                    broker_dry_run = bool(response_data.get("dry_run"))
                    ibkr_results = response_data.get("results", [])
                    ibkr_errors = response_data.get("errors", [])
                    if not DRY_RUN and broker_dry_run:
                        ibkr_results = []
                        ibkr_errors.extend(
                            {
                                "order_id": o.get("order_id"),
                                "client_order_id": o.get("client_order_id"),
                                "error": "IBKR_BROKER_STILL_IN_DRY_RUN",
                            }
                            for o in pending_orders
                        )
                    elif ibkr_results:
                        order_keys = set()
                        for o in pending_orders:
                            order_keys.add(str(o.get("order_id") or ""))
                            order_keys.add(str(o.get("client_order_id") or ""))
                        order_keys.discard("")
                        matched_fills, broker_fills = poll_recent_fills(order_keys)
    except (URLError, TimeoutError, Exception) as exc:
        ibkr_errors.append({"error": f"ibkr-broker unreachable: {exc}", "fallback": "sandbox_only"})

result_map = {
    (r.get("order_id") or r.get("client_order_id")): r
    for r in ibkr_results
    if r.get("order_id") or r.get("client_order_id")
}
error_map = {
    (e.get("order_id") or e.get("client_order_id")): e
    for e in ibkr_errors
    if e.get("order_id") or e.get("client_order_id")
}

for order in executable_orders:
    oid = order.get("order_id")
    cid = order.get("client_order_id")
    result = result_map.get(oid) or result_map.get(cid)
    error = error_map.get(oid) or error_map.get(cid)

    if result:
        result_error = broker_result_error(result)
        result_broker_order_id = broker_order_id(result)
        order["ibkr_status"] = result.get("status", "unknown")
        order["ibkr_response"] = result
        order["broker"] = "IBKR"
        order["broker_order_id"] = result_broker_order_id
        fill = matched_fills.get(str(oid or "")) or matched_fills.get(str(cid or ""))
        if result_error:
            order["ibkr_status"] = "error"
            order["ibkr_error"] = result_error
            if not DRY_RUN:
                order["status"] = "broker_error"
                order["rejection_reason"] = "IBKR_BROKER_ERROR"
        elif fill:
            order["status"] = "filled"
            order["ibkr_status"] = "filled"
            order["ibkr_fill"] = fill
            order["ibkr_filled_at"] = fill.get("trade_time") or fill.get("tradeTime") or fill.get("time")
        elif not DRY_RUN and not result_broker_order_id:
            order["ibkr_status"] = "error"
            order["ibkr_error"] = "IBKR_SUBMISSION_WITHOUT_ORDER_ID"
            order["status"] = "broker_error"
            order["rejection_reason"] = "IBKR_BROKER_ERROR"
        elif not DRY_RUN:
            order["status"] = "submitted"
    elif error:
        order["ibkr_status"] = "error"
        order["ibkr_error"] = error.get("error", "")
        order["broker"] = "IBKR"
        if not DRY_RUN:
            order["status"] = "broker_error"
            order["rejection_reason"] = "IBKR_BROKER_ERROR"
    elif DRY_RUN:
        order["ibkr_status"] = "dry_run"
        order["broker"] = "SIM"
    elif order.get("status") == "pending":
        order["ibkr_status"] = "not_sent"
        order["broker"] = "IBKR"
        order["status"] = "broker_error"
        order["rejection_reason"] = "IBKR_NOT_SENT"
    else:
        order["ibkr_status"] = "not_sent"

return [
    {
        "json": {
            **ctx,
            "executable_orders": executable_orders,
            "ibkr_send_summary": {
                "dry_run": DRY_RUN,
                "broker_dry_run": broker_dry_run,
                "broker_called": broker_called,
                "orders_considered": len(pending_orders),
                "orders_sent": len(ibkr_results),
                "errors": len(ibkr_errors),
                "fills_matched": len(matched_fills),
                "fills_seen": len(broker_fills),
                "broker_url": BROKER_URL,
                "errors_detail": ibkr_errors,
                "health": broker_health,
                "paper_account_guard": {
                    "required": REQUIRE_PAPER_ACCOUNT,
                    "prefixes": list(PAPER_ACCOUNT_PREFIXES),
                    "detected_accounts": paper_account_ids(broker_positions),
                },
            },
        }
    }
]

import json
import os
import re
from datetime import datetime, timezone

FEE_BPS = 0.5
LOT_UNITS = 100000

ctx = (_items or [{"json": {}}])[0].get("json", {})
orders = ctx.get("executable_orders") or []
brief = ctx.get("brief") or {}
dry_run = os.environ.get("IBKR_DRY_RUN", "true").lower() != "false"

prices = {r.get("pair"): r.get("last_close") for r in brief.get("technical_signals", []) if r.get("pair")}
meta = {r.get("pair"): r for r in (brief.get("universe", {}).get("metadata") or [])}
open_lots = {
    str(l.get("lot_id") or ""): l
    for l in ((brief.get("portfolio_state") or {}).get("open_lots") or [])
    if l.get("lot_id")
}


def normalize_timestamp(value):
    if value is None or value == "":
        return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
    text = str(value).strip()
    if re.match(r"^\d{8}-\d{2}:\d{2}:\d{2}$", text):
        return f"{text[0:4]}-{text[4:6]}-{text[6:8]} {text[9:17]}"
    if "T" in text:
        text = text.replace("T", " ")
    if text.endswith("Z"):
        text = text[:-1].strip()
    if re.match(r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}", text):
        return text
    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")


def valid_close_order(order):
    side = order.get("side")
    if side not in {"close_long", "close_short"}:
        return True
    lot = open_lots.get(str(order.get("lot_id_to_close") or ""))
    if not lot:
        order["status"] = "rejected"
        order["rejection_reason"] = "LOT_TO_CLOSE_NOT_FOUND"
        return False
    expected_side = "close_long" if lot.get("side") == "long" else "close_short" if lot.get("side") == "short" else ""
    if side != expected_side:
        order["status"] = "rejected"
        order["rejection_reason"] = "CLOSE_SIDE_MISMATCH"
        return False
    size_lots = float(order.get("size_lots") or 0)
    lot_size = float(lot.get("size_lots") or 0)
    if size_lots <= 0 or size_lots > lot_size + 1e-9:
        order["status"] = "rejected"
        order["rejection_reason"] = "CLOSE_SIZE_INVALID"
        return False
    return True


def to_float(value, default=0.0):
    try:
        if value is None or value == "":
            return default
        text = str(value).replace(",", "").strip()
        if not text:
            return default
        n = float(text)
        return n if n == n and abs(n) != float("inf") else default
    except Exception:
        return default


def quote_to_eur(ccy):
    ccy = str(ccy or "").upper().strip()
    if ccy == "EUR":
        return 1.0
    direct = to_float(prices.get(f"{ccy}EUR"), 0.0)
    if direct > 0:
        return direct
    inverse = to_float(prices.get(f"EUR{ccy}"), 0.0)
    if inverse > 0:
        return 1.0 / inverse
    if ccy == "USD":
        eurusd = to_float(prices.get("EURUSD"), 0.0)
        return 1.0 / eurusd if eurusd > 0 else 1.0
    ccy_usd = to_float(prices.get(f"{ccy}USD"), 0.0)
    usd_ccy = to_float(prices.get(f"USD{ccy}"), 0.0)
    eurusd = to_float(prices.get("EURUSD"), 0.0)
    usd_eur = 1.0 / eurusd if eurusd > 0 else 0.0
    if ccy_usd > 0 and usd_eur > 0:
        return ccy_usd * usd_eur
    if usd_ccy > 0 and usd_eur > 0:
        return (1.0 / usd_ccy) * usd_eur
    return 1.0


def ibkr_commission_fields(raw):
    amount = None
    amount_field = ""
    for field in ("commission", "ibCommission", "ib_commission", "commission_amount", "fees_eur", "fee"):
        if raw.get(field) not in (None, ""):
            amount = to_float(raw.get(field), 0.0)
            amount_field = field
            break
    ccy = ""
    for field in ("commissionCurrency", "commission_currency", "commission_ccy", "ibCommissionCurrency", "feeCurrency"):
        if raw.get(field) not in (None, ""):
            ccy = str(raw.get(field)).upper().strip()
            break
    if amount is None:
        return {
            "fee_amount": 0.0,
            "fee_ccy": "",
            "fees_eur": 0.0,
            "fee_source": "ibkr_commission_missing",
        }
    if not ccy:
        ccy = "EUR"
        source = f"ibkr_{amount_field}_assumed_eur_no_ccy"
    elif ccy == "EUR":
        source = f"ibkr_{amount_field}_reported_eur"
    else:
        source = f"ibkr_{amount_field}_converted_{ccy}_to_eur"
    return {
        "fee_amount": abs(amount),
        "fee_ccy": ccy,
        "fees_eur": abs(amount) * quote_to_eur(ccy),
        "fee_source": source,
    }


def fill_from_ibkr(order):
    raw = order.get("ibkr_fill") or {}
    if not isinstance(raw, dict):
        return None
    pair = order.get("pair")
    price = raw.get("price") or raw.get("avgPrice") or raw.get("avg_price")
    size = raw.get("size") or raw.get("quantity") or raw.get("shares") or raw.get("filledQuantity")
    try:
        price = float(str(price).replace(",", ""))
        size_units = abs(float(str(size).replace(",", "")))
    except Exception:
        return None
    if price <= 0 or size_units <= 0:
        return None
    size_lots = size_units / LOT_UNITS
    fee = ibkr_commission_fields(raw)
    fill_id = raw.get("execution_id") or raw.get("execId") or raw.get("id") or f"FIL_{order['order_id']}"
    filled_at = raw.get("trade_time") or raw.get("tradeTime") or raw.get("time") or order.get("ibkr_filled_at")
    filled_at = normalize_timestamp(filled_at)
    return {
        "fill_id": f"IBKR_{fill_id}",
        "order_id": order["order_id"],
        "pair": pair,
        "side": order.get("side"),
        "fill_price": price,
        "fill_size_lots": size_lots,
        "fees_eur": fee["fees_eur"],
        "fee_amount": fee["fee_amount"],
        "fee_ccy": fee["fee_ccy"],
        "fee_source": fee["fee_source"],
        "broker": "IBKR",
        "broker_execution_id": str(fill_id),
        "raw_fill_json": json.dumps(raw, ensure_ascii=False),
        "swap_eur": 0.0,
        "filled_at": filled_at,
        "fill_source": "ibkr_confirmed",
        "lot_id_to_close": order.get("lot_id_to_close") or "",
    }


fills = []
if dry_run:
    for o in orders:
        if o.get("status") != "pending":
            continue
        if not valid_close_order(o):
            continue
        pair = o.get("pair")
        px = float(prices.get(pair) or 0)
        if px <= 0:
            continue
        pip = float((meta.get(pair) or {}).get("pip_size") or (0.01 if str(pair).endswith("JPY") else 0.0001))
        fill_price = px + pip if o.get("side") in {"buy_base", "close_short"} else px - pip
        notional_eur = abs(float(o.get("notional_eur") or 0))
        fees_eur = FEE_BPS * notional_eur / 10000.0
        fills.append({
            "fill_id": f"FIL_{o['order_id']}",
            "order_id": o["order_id"],
            "pair": pair,
            "side": o.get("side"),
            "fill_price": fill_price,
            "fill_size_lots": float(o.get("size_lots") or 0),
            "fees_eur": fees_eur,
            "fee_amount": fees_eur,
            "fee_ccy": "EUR",
            "fee_source": "simulated_bps",
            "broker": "SIM",
            "broker_execution_id": "",
            "raw_fill_json": "",
            "swap_eur": 0.0,
            "filled_at": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S"),
            "fill_source": "simulated_yfinance",
            "lot_id_to_close": o.get("lot_id_to_close") or "",
        })
else:
    for o in orders:
        if o.get("status") != "filled":
            continue
        if not valid_close_order(o):
            continue
        fill = fill_from_ibkr(o)
        if fill:
            fills.append(fill)

rejection_reasons = {}
for o in orders:
    if o.get("status") == "rejected":
        reason = o.get("rejection_reason") or "UNKNOWN"
        rejection_reasons[reason] = rejection_reasons.get(reason, 0) + 1

safety_summary = {
    **(ctx.get("safety_summary") or {}),
    "rejected_orders_count": sum(rejection_reasons.values()),
    "rejection_reasons": rejection_reasons,
}

return [{"json": {**ctx, "executable_orders": orders, "fills": fills, "safety_summary": safety_summary}}]
